#include<bits/stdc++.h>
#define int long long
using namespace std;
int dp[555555][66];
int a[222222];
signed main(){
	int n,k;
	cin>>n>>k;
	for(int i=1;i<=n;i++){
		cin>>a[i];
	}
	for(int i=1;i<=n;i++){
		for(int j=0;j<=30;j++){
			dp[i][j]=n+1;
		}
	}
	for(int i=1;i<=n;i++){
		dp[i][0]=a[i];
	}
	for(int j=1;j<=30;j++){
		for(int i=1;i<=n;i++){
			dp[i][j]=dp[dp[i][j-1]][j-1];
		}
	}
	int x=1;
	for(int i=30;i>=0;i--){
		if((1<<i)<=k){
			k-=(1<<i);
			x=dp[x][i];
		}
	}
	cout<<x<<endl;
	return 0;
}

这是我这道题的倍增解法，你看看。

你的倍增思路是对的，转移式 `dp[i][j] = dp[dp[i][j-1]][j-1]` 也正确：从城市 `i` 连跳两次 \(2^{j-1}\) 步，就等于跳 \(2^j\) 步。**问题在于倍增只算到了第 30 位，不够覆盖 \(K\le 10^{18}\)。**

你从大到小枚举、能跳就跳的写法可以保留，只需注意两点：

1. **预处理和查询都要覆盖第 `0` 到 `59` 位**，因为 \(10^{18}<2^{60}\)。原代码即使把第 `0` 到 `30` 位全用上，也只能跳 \(2^{31}-1\) 步。
2. **把 `1 << j` 改成 `1LL << j`**。`#define int long long` 不会改变字面量 `1` 的类型；把循环扩到 `59` 后，不能再用普通 `int` 做这个移位。

按你的思路，代码可以写成：

```cpp
#include <bits/stdc++.h>
using namespace std;

constexpr int LOG = 60;
int dp[LOG][200001];  // dp[j][i]：从城市 i 跳 2^j 步后的位置

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long k;
    cin >> n >> k;

    for (int i = 1; i <= n; ++i)
        cin >> dp[0][i];

    for (int j = 1; j < LOG; ++j)
        for (int i = 1; i <= n; ++i)
            dp[j][i] = dp[j - 1][dp[j - 1][i]];

    int x = 1;
    for (int j = LOG - 1; j >= 0; --j) {
        if ((1LL << j) <= k) {
            k -= 1LL << j;
            x = dp[j][x];
        }
    }

    cout << x << '\n';
}
```

不需要把 `dp` 初始化为 `n+1`：第 `0` 层由输入填满，之后每层都只读取已经算好的上一层。表里存的是不超过 \(2\times10^5\) 的**城市编号**，所以 `dp` 用 `int` 就够了；需要 64 位的是**步数** `k` 和移位表达式。
